// WF3 - "Describe failure"
// Entrada: el payload del nodo Error Trigger. Salida: el evento SANEADO que se registra en Django.
// Responde a: que workflow fallo, en que etapa, de que tipo, que se puede registrar sin riesgo y si conviene reintentar.
// ---- Redaccion de datos personales (snippets/redact.js) ----
// Se aplica al texto ANTES de enviarlo a cualquier servicio externo (el LLM). Es la misma regla que
// backend/tickets/privacy.py, que Django aplica por su lado al guardar los mensajes de error.
// Pecar de redactar de mas es lo seguro; el correo del cliente nunca viaja al LLM.
const EMAIL_RE = /[\p{L}\p{N}_.+-]+@[\p{L}\p{N}-]+(?:\.[\p{L}\p{N}-]+)+/gu;
// 9+ digitos con hasta 2 separadores entre digitos. Sin puntos entre digitos: una IP (172.20.0.3) o una version no son
// telefonos. Un punto FINAL de frase si se admite ("llamame al +34 612 345 678."), pero no un punto seguido de digito
// (decimal): `(?!\w|\.\d)`. Un `(?![\w.])` dejaba SIN redactar los telefonos al final de una frase.
const PHONE_RE = /(?<![\w.])(?:\+|\()?\d(?:[\s()-]{0,2}\d){8,}(?!\w|\.\d)/g;

const redactPii = (text) =>
  String(text === undefined || text === null ? '' : text).replace(EMAIL_RE, '[email]').replace(PHONE_RE, '[phone]');
// ---- Utilidades compartidas (el builder las inlinea en cada nodo Code que hace `// @include shared.js`) ----
// Fuente unica: n8n/src/snippets/shared.js. No editar la copia dentro del JSON del workflow.

// external_id llega del cliente SIN validar: solo se propaga si tiene el formato permitido.
const safeExternalId = (value) => (typeof value === 'string' && /^[A-Za-z0-9._-]{1,64}$/.test(value) ? value : '');

// Texto corto y en una linea, apto para registrar. Nunca se vuelca un payload completo.
const shortDetail = (value) =>
  String(value === undefined || value === null ? '' : value).replace(/\s+/g, ' ').trim().slice(0, 200);

// El error de un nodo HTTP puede llegar como texto o como objeto.
const errorText = (err) => {
  if (err === undefined || err === null) return '';
  if (typeof err === 'string') return err;
  return [err.message, err.description, err.code, err.httpCode ? `HTTP ${err.httpCode}` : '']
    .filter(Boolean)
    .join(' | ');
};

// Mensaje del nodo "Stop and Error" que lee WF3. n8n SUSTITUYE el mensaje de un error si contiene (sin
// distinguir mayusculas) codigos como ECONNREFUSED, EAI_AGAIN o ENOENT. Un external_id elegido por el cliente
// o el texto de un error de red pueden contenerlos, asi que la carga va en HEXADECIMAL: ninguno de esos
// codigos puede aparecer en un texto 0-9a-f (todos incluyen alguna letra fuera de a-f).
// `type` y `retryable` son vocabulario controlado y se dejan en claro para leerlos en la interfaz.
const encodeFailure = (failure) => {
  const ascii = JSON.stringify(failure).replace(/[^\x00-\x7f]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, '0')}`);
  const hex = ascii.split('').map((ch) => ch.charCodeAt(0).toString(16).padStart(2, '0')).join('');
  return `HANDLED_FAILURE type=${failure.type} retryable=${failure.retryable} data=${hex}`;
};

// Inversa de encodeFailure (la usa WF3). Devuelve null si el mensaje no es un fallo gestionado.
const decodeFailure = (message) => {
  const m = /data=([0-9a-f]+)/.exec(String(message || ''));
  if (!m || m[1].length % 2 !== 0) return null;
  try {
    return JSON.parse(m[1].match(/../g).map((h) => String.fromCharCode(parseInt(h, 16))).join(''));
  } catch (e) {
    return null;
  }
};

// Anade `failure_message` (lo que lanzara "Stop and Error") a un item que lleve un `failure`.
const withFailureMessage = (json) => (json.failure ? { ...json, failure_message: encodeFailure(json.failure) } : json);

// Traduce un fallo de red/HTTP a: tipo de error (para el registro), respuesta al cliente y si es reintentable.
//   retryable: 'yes' = repetir es seguro (operacion idempotente) | 'no' = hay que corregir algo | 'manual' = decide una persona
// Algunos errores HTTP de n8n llegan como TEXTO que empieza por el codigo (p. ej. `404 - "{...cuerpo...}"`), sin httpCode.
const leadingStatus = (text) => {
  const m = /^\s*(\d{3})\b/.exec(text);
  return m ? Number(m[1]) : NaN;
};

const classifyError = (err) => {
  const text = errorText(err).toLowerCase();
  const http = Number(err && typeof err === 'object' ? err.httpCode || err.statusCode : NaN) || leadingStatus(text);
  // Se reconocen tanto los codigos crudos (ECONNABORTED...) como los textos "amigables" con que n8n los reescribe
  // (STATUS_CODE_MESSAGES y COMMON_ERRORS en n8n-workflow).
  if (/timeout|timed out|etimedout|econnaborted|connection was aborted|gateway timed out/.test(text)) {
    return { type: 'timeout', status: 504, code: 'upstream_timeout', retryable: 'yes' };
  }
  if (/econnrefused|enotfound|eai_again|ehostunreach|econnreset|socket hang up|getaddrinfo|network|perhaps the server is offline|perhaps it is offline|refused the connection|dns server|connection cannot be established|closed unexpectedly/.test(text)) {
    return { type: 'connection', status: 503, code: 'upstream_unavailable', retryable: 'yes' };
  }
  if (http >= 500 || /not able to process your request|failed to process your request|bad gateway|service unavailable/.test(text)) {
    return { type: 'http_5xx', status: 502, code: 'upstream_error', retryable: 'yes' };
  }
  if (http >= 400 || /authorization failed|check your credentials|forbidden|bad request|could not be found|method not allowed|payment required|request is invalid/.test(text)) {
    return { type: 'http_4xx', status: 502, code: 'upstream_rejected', retryable: 'no' };
  }
  return { type: 'unknown', status: 502, code: 'upstream_error', retryable: 'manual' };
};

const input = $input.first().json;
const wf = input.workflow || {};
const exec = input.execution || null; // ejecucion que fallo
const trig = input.trigger || null; // el fallo fue al ACTIVAR el trigger: la ejecucion nunca llego a existir

const ERROR_TYPES = ['http_4xx', 'http_5xx', 'timeout', 'connection', 'validation', 'ai_output', 'smtp', 'unknown'];
const RETRYABLE = ['no', 'yes', 'manual'];
const AI_NODES = ['Prepare AI input', 'Triage with AI', 'OpenAI Chat Model', 'Validate AI output', 'AI call failed'];

const rawMessage = String(
  (exec && exec.error && exec.error.message)
  || (trig && trig.error && (trig.error.message || (trig.error.cause && trig.error.cause.message)))
  || '',
);
const lastNode = String((exec && exec.lastNodeExecuted) || (trig && trig.error && trig.error.node && trig.error.node.name) || '');

// 1) Fallo GESTIONADO por el propio workflow (mensaje HANDLED_FAILURE codificado): trae tipo, ticket y detalle fiables.
const handled = decodeFailure(rawMessage);

// 2) Fallo NO gestionado: se deduce de la etapa (ultimo nodo) y del texto del error.
const classifyRaw = () => {
  if (/^VALIDATION:/.test(rawMessage) || lastNode === 'Validate input') return { type: 'validation', retryable: 'no' };
  if (/execution.*(timed out|timeout)|timed out after \d+/i.test(rawMessage)) return { type: 'timeout', retryable: 'manual' };
  if (lastNode === 'Send notification email') return { type: 'smtp', retryable: 'manual' };
  if (AI_NODES.includes(lastNode)) return { type: 'ai_output', retryable: 'manual' };
  const c = classifyError({ message: rawMessage });
  return { type: c.type, retryable: c.retryable };
};

const info = handled
  ? {
    type: ERROR_TYPES.includes(handled.type) ? handled.type : 'unknown',
    retryable: RETRYABLE.includes(handled.retryable) ? handled.retryable : 'manual',
    node: String(handled.node || lastNode),
    detail: handled.detail,
    ticketId: handled.ticket_id,
    externalId: handled.ticket_external_id,
  }
  : { ...classifyRaw(), node: lastNode, detail: rawMessage, ticketId: null, externalId: '' };

// SANEADO: nunca se registra el payload ni datos personales; solo ids, etapa, tipo y un detalle corto y redactado.
const event = {
  workflow_id: String(wf.id || ''),
  workflow_name: String(wf.name || 'unknown workflow').slice(0, 200),
  execution_id: exec && exec.id !== undefined && exec.id !== null ? String(exec.id) : '',
  failed_node: info.node.slice(0, 200),
  error_type: info.type,
  retryable: info.retryable,
  message: redactPii(shortDetail(info.detail)).slice(0, 500),
  ticket_id: Number.isInteger(info.ticketId) && info.ticketId > 0 ? info.ticketId : null,
  ticket_external_id: safeExternalId(info.externalId),
};

const url = exec && typeof exec.url === 'string' && /^https?:\/\/\S+$/.test(exec.url) ? exec.url : '';
return [{ json: { event, execution_url: url, handled: handled !== null } }];

// WF3 - "Compose alert email"
// Salida de ERROR de "Register event in Django": el fallo NO pudo registrarse (p. ej. Django caido, justo lo que suele
// fallar). Para que no se pierda en silencio se avisa por correo con el mismo evento SANEADO. Si el SMTP tambien
// estuviera caido, el unico rastro seria el historial de ejecuciones de n8n.
// ---- Utilidades compartidas (el builder las inlinea en cada nodo Code que hace `// @include shared.js`) ----
// Fuente unica: n8n/src/snippets/shared.js. No editar la copia dentro del JSON del workflow.

